export async function apiRequest<T>(
  endpoint: string,
  options: RequestInit = {},
): Promise<T> {
  const path = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
  const url = API_URL ? `${API_URL.replace(/\/$/, '')}${path}` : path;

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
