export type OAuthProvider = 'google' | 'github';

export interface OAuthStateRecord {
  provider: OAuthProvider;
  redirectUri: string;
  frontendOrigin: string;
  createdAt: string;
}

interface GoogleTokenResponse {
  access_token: string;
}

interface GoogleUserResponse {
