      forks: repoData.forks_count,
      open_issues: repoData.open_issues_count,
      created_at: repoData.created_at,
      updated_at: repoData.updated_at,
    });
  } catch {
    return errorResponse(c, 502, 'ANALYZE_FAILED', 'Failed to analyze repository');
