    'INSERT INTO users (id, email, name, password_hash, created_at) VALUES (?, ?, ?, ?, ?)'
  ).bind(id, email, name, hash, new Date().toISOString()).run();
}

/** Clear the auth rate limit counter in KV to avoid cross-test interference */
